async searchMentions({ state }, { query, limit = 10, onResults }) {
  const project = state.activeProject
  if (!project?.$state) return []

  const relatedProjects = getRelatedProjects(project)
  const allProjectsToSearch = [project, ...relatedProjects]

  const seenKeys = new Set()
  const allMentions = []

  // Process each project and emit results as they complete
  for (const proj of allProjectsToSearch) {
    try {
      await Promise.all([
        ensureFilesLoaded(proj),
        ensureProfilesLoaded(proj)
      ])

      const projMentions = await buildMentions(proj)
      const fileResults = query && query.length >= 2 
        ? await searchProjectFiles(proj, query, limit)
        : []

      // Combine mentions and files
      const combined = [
        ...projMentions,
        ...fileResults.map(fileResult => ({
          name: fileResult.name,
          file: fileResult.file,
          project: fileResult.project,
          searchIndex: fileResult.searchIndex,
          avatar: fileResult.project?.project_icon,
          mention: encodeURIComponent(fileResult.name)
        }))
      ]

      // Deduplicate and collect
      for (const mention of combined) {
        const key = mention.file || mention.name
        if (!seenKeys.has(key)) {
          seenKeys.add(key)
          allMentions.push(mention)
        }
      }

      // Emit intermediate results
      if (onResults) {
        const fuseOptions = {
          includeScore: true,
          minMatchCharLength: 3,
          keys: ["name", "searchIndex", "file"]
        }
        const fuse = new Fuse(allMentions, fuseOptions)
        const filtered = fuse.search(query)
          .filter(({ score }) => score < 0.25)
          .map(r => r.item)
          .slice(0, limit)
        onResults(filtered)
      }
    } catch (error) {
      console.error(`Error searching in project ${proj.project_name}:`, error)
    }
  }

  // Return final results
  const fuseOptions = {
    includeScore: true,
    minMatchCharLength: 3,
    keys: ["name", "searchIndex", "file"]
  }
  const fuse = new Fuse(allMentions, fuseOptions)
  return fuse.search(query)
    .filter(({ score }) => score < 0.25)
    .map(r => r.item)
    .slice(0, limit)
}

async runIntelliSense() {
  if (this.intelliSenseDismissed) return
  const { word } = this.cursorWord
  if (!word?.startsWith('@')) {
    this.intelliSenseSuggestions = []
    return
  }
  const rawQuery = word.slice(1)
  if (!rawQuery || rawQuery.trim().length < 3) {
    this.intelliSenseSuggestions = []
    return
  }
  this.intelliSenseQuery = rawQuery
  this.intelliSenseIndex = 0

  // Use streaming results with onResults callback
  await (
    this.chatProject?.$state?.searchMentions?.(rawQuery, 10, (results) => {
      // Update suggestions as results come in
      this.intelliSenseSuggestions = results
      this.intelliSenseIndex = 0
    })
    || this.$projects.searchMentions?.({
      query: rawQuery,
      limit: 10,
      onResults: (results) => {
        this.intelliSenseSuggestions = results
        this.intelliSenseIndex = 0
      }
    })
    || Promise.resolve([])
  )
}

