  const relatedProjects = getRelatedProjects(project)
  const allProjectsToSearch = [project, ...relatedProjects]

  const seenKeys = new Set()
  const searchResults = []

  // Process each project and collect results with scores
  for (const proj of allProjectsToSearch) {
    try {
      const projectResults = await searchProjectMentions(proj, query, limit)

      // Deduplicate and collect results with scores
      for (const mention of projectResults) {
        const key = mention.file || mention.name
        if (!seenKeys.has(key)) {
          seenKeys.add(key)
          searchResults.push(mention)
        }
      }

      // Emit intermediate results filtered by score
      if (onResults) {
        const filtered = searchResults
          .filter(({ score }) => score < 0.25)
          .slice(0, limit)
        onResults(filtered)
      }
    } catch (error) {
      console.error(`Error searching in project ${proj.project_name}:`, error)
    }
  }

  // Return final results filtered by score
  return searchResults
    .filter(({ score }) => score < 0.25)
    .slice(0, limit)
}

